"""stage6_data.py (Ch 20-23 終極無矛盾版)"""

STAGE_6 = {'title': '第六階：物理場域實戰、儲能、磁場與熱力學降維統御（第 20–23 堂）', 'theme': '單變數定積分縱深推進，熱力學絕熱過程，三位一體儲能相空間對偶，電流磁效應微元場積分與剛體轉動慣量', 'lessons': [{'id': 20, 'title': '熱力學微積分：絕熱過程 PV^gamma = C 與氣體做功（第一定律微分式分離變數法）', 'book_blueprint': '高中物理熱學的核心公式群：氣體做功 W = int P dV、等溫過程膨脹功 W = nRT ln(V_2/V_1)、熱力學第一定律 dQ = dU + dW，以及最神秘的絕熱過程方程 P V^gamma = C（gamma = C_p / C_v）。高中課本只能要求學生硬記 P-V 圖上『絕熱線比等溫線更陡峭』，卻無法給出任何數學推導。本章以熱力學微積分微分形式開局：內能微元 dU = n C_v dT；等溫過程 T 恆定，代入理想氣體狀態方程 P = nRT/V，定積分直接收穫自然對數功 W = nRT int (1/V) dV = nRT ln(V_2/V_1)；絕熱過程與外界無熱交換 dQ = 0，第一定律化為 n C_v dT = -P dV = -(nRT/V) dV，分離變數法分離溫度與體積：C_v (dT/T) = -R (dV/V)；引用邁耶關係式 C_p - C_v = R，兩邊同除以 C_v 得 dT/T + (gamma - 1) dV/V = 0，兩端定積分收穫 ln(T V^{gamma-1}) = const，再由 T 正比於 PV 徹底鎖定 P V^gamma = C！最後推導絕熱過程對外做功公式 W = (P_1 V_1 - P_2 V_2)/(gamma - 1)，徹底打通熱力學微積分命脈。', 'dojo_core': '黑板四分區實彈攻防：一區在 P-V 圖上並列畫出等溫線（斜率 -P/V）與絕熱線（斜率 -gamma P/V），標註陰影面積代表的做功積分；二區無跳步推導 dQ = 0 下的分離變數法，展示邁耶關係如何引入熱容比 gamma；三區在黑板推導絕熱膨脹功的兩種等價形式；四區以『用等溫功公式硬算絕熱做功』的典型錯解突襲學員，展示熱力學微分方程的約束力量。', 'formulas': [{'id': 'Eq 20.1', 'name': '氣體體積變化做功微元式', 'latex': '\\mathrm{d}W = P\\,\\mathrm{d}V \\implies W = \\int_{V_1}^{V_2} P(V)\\,\\mathrm{d}V'}, {'id': 'Eq 20.2', 'name': '等溫過程定積分做功公式', 'latex': 'W_{\\text{iso}} = \\int_{V_1}^{V_2} \\frac{nRT}{V}\\,\\mathrm{d}V = nRT \\ln\\left(\\frac{V_2}{V_1}\\right)'}, {'id': 'Eq 20.3', 'name': '熱力學第一定律微分形式', 'latex': '\\mathrm{d}Q = \\mathrm{d}U + \\mathrm{d}W = n C_v\\,\\mathrm{d}T + P\\,\\mathrm{d}V'}, {'id': 'Eq 20.4', 'name': '邁耶公式與熱容比定義', 'latex': 'C_p - C_v = R, \\quad \\gamma = \\frac{C_p}{C_v} = 1 + \\frac{R}{C_v}'}, {'id': 'Eq 20.5', 'name': '絕熱過程微分分離變數式', 'latex': 'n C_v\\,\\mathrm{d}T = -P\\,\\mathrm{d}V = -\\frac{nRT}{V}\\,\\mathrm{d}V \\implies \\frac{\\mathrm{d}T}{T} + (\\gamma - 1)\\frac{\\mathrm{d}V}{V} = 0'}, {'id': 'Eq 20.6', 'name': '絕熱狀態方程三位一體式', 'latex': 'P V^\\gamma = C_1, \\quad T V^{\\gamma-1} = C_2, \\quad T^\\gamma P^{1-\\gamma} = C_3'}, {'id': 'Eq 20.7', 'name': '絕熱過程對外做功封閉解式', 'latex': 'W_{\\text{adi}} = -\\Delta U = n C_v (T_1 - T_2) = \\frac{P_1 V_1 - P_2 V_2}{\\gamma - 1}'}], 'problems': {'worked_examples': [{'id': 'Ex 20.1', 'desc': '在 P-V 座標系中，分別求等溫線與絕熱線在同一狀態點 (P_0, V_0) 的斜率 (dP/dV)，嚴格證明絕熱線斜率恆為等溫線斜率的 gamma 倍。'}, {'id': 'Ex 20.2', 'desc': '1 莫耳單原子理想氣體（gamma = 5/3）自狀態 (P_0, V_0) 絕熱膨脹至 8 V_0，求末態壓強、末態溫度，以及氣體對外所做的總功。'}, {'id': 'Ex 20.3', 'desc': '卡諾循環（Carnot Cycle）：包含兩條等溫線與兩條絕熱線，利用微積分分段做功積分，嚴格推導卡諾熱機效率 eta = 1 - T_L / T_H。'}], 'margin_inquiries': [{'id': 'Q1 20.1', 'desc': '為什麼等溫做功積分會自然產生自然對數 ln，而絕熱做功積分卻能還原為代數式 (P_1 V_1 - P_2 V_2)/(gamma - 1)？'}, {'id': 'Q1 20.2', 'desc': '單原子氣體 gamma = 5/3，雙原子氣體 gamma = 7/5，這個比值與分子的微觀自由度有何微積分關聯？'}, {'id': 'Q1 20.3', 'desc': '快速拔出自行車打氣筒活塞時筒壁發燙，這是絕熱壓縮過程；用微分式 dT = - (P/n C_v) dV 解釋溫度為何必然升高。'}], 'foundational_drills': [{'id': 'P1 20.1', 'desc': '理想氣體在壓強隨體積線性增加 P(V) = alpha V 過程中膨脹，求自 V_1 到 V_2 過程氣體所做的總功。'}, {'id': 'P1 20.2', 'desc': '證明理想氣體任意多方過程 P V^n = C 的摩爾熱容為 C_n = C_v + R / (1 - n)。'}, {'id': 'P1 20.3', 'desc': '2 莫耳理想氣體在 300K 等溫膨脹至原體積的 3 倍，求氣體吸收的熱量（R = 8.314 J/(mol*K)）。'}, {'id': 'P1 20.4', 'desc': '利用微分方程推導絕熱過程溫度與壓強的關係式 T^gamma P^{1-gamma} = const。'}], 'interdisciplinary_applications': [{'id': 'P5 20.1', 'desc': '【大氣對流與絕熱直減率】上升氣團因外界氣壓隨高度降低而絕熱膨脹冷卻，結合流體靜力學微商 dP = -rho g dz 與絕熱方程，推導大氣溫度直減率 dT/dz = -g / C_p（約 9.8 K/km）。'}, {'id': 'P5 20.2', 'desc': '【聲速在空氣中的微積分推導】牛頓誤將空氣壓縮視為等溫過程得出聲速 v = sqrt{P/rho}，拉普拉斯利用絕熱過程微商 (dP/drho) = gamma P/rho 正確導出聲速 v = sqrt{gamma P / rho}，手算驗證 331 m/s 的精確數值。'}, {'id': 'P5 20.3', 'desc': '【內燃機奧圖循環效率】由兩條等容線與兩條絕熱線構成汽油機循環，利用絕熱壓縮比 r = V_max / V_min 導出熱效率 eta = 1 - 1 / r^{gamma-1}。'}, {'id': 'P5 20.4', 'desc': '【化學爆炸衝擊波】高壓氣體爆炸在瞬間形成絕熱激波前鋒，利用微元能量守恆分析激波跨界面的壓強與溫度突躍。'}], 'deepwater_challenges': [{'id': 'P9 20.1', 'desc': '非理想范德華氣體 (P + a/V^2)(V - b) = RT，無跳步計算其等溫可逆膨脹做功公式 W = int P dV，指出分子引力項 a 與排斥體積 b 對做功的修正。'}, {'id': 'P9 20.2', 'desc': '推導自由膨脹（焦耳膨脹）的不可逆性：氣體向真空膨脹 W=0, Q=0, Delta U=0，但系統微觀態數暴增，定積分計算其熱力學熵增 Delta S = n R ln(V_2/V_1)。'}], 'dojo_defense_tasks': [{'id': 'D1 20.1', 'desc': '學員計算絕熱做功套用等溫公式 W = nRT ln(V_2/V_1)，導師截停：『絕熱過程溫度是常數嗎？溫度一直在變，你的 T 代入哪個值？立刻重寫第一定律微商！』'}, {'id': 'D1 20.2', 'desc': '學員在黑板推導絕熱方程遺漏負號，寫出 C_v dT = P dV，導師逼問：『氣體對外膨脹做功，內能難道還會增加？指出能量守恆的符號定義！』'}, {'id': 'D1 20.3', 'desc': '學員無法解釋為什麼牛頓算出的聲速比實驗值小了 15%，導師在黑板寫出聲波震盪週期微元，要求其闡釋為何高頻聲波是絕熱而非等溫。'}], 'unseen_sandbox_scenarios': [{'id': 'U1 20.1', 'desc': '未知破局：設某氣體狀態方程為 P(V - b) = nRT，求其絕熱過程狀態方程 P 與 V 的解析表達式。'}, {'id': 'U1 20.2', 'desc': '未知破局：一氣缸被絕熱活塞分為兩半，左側電熱絲緩慢加熱，右側絕熱壓縮，求解兩側壓強與體積演化的聯立微分關係。'}, {'id': 'U1 20.3', 'desc': '未知破局：給定一橢圓形 P-V 封閉循環，要求學員不使用數值積分，純粹由橢圓幾何面積公式求出循環淨做功。'}], 'system_trivialization_arsenal': [{'id': 'K1 20.1', 'desc': '體制內考題秒殺：高中熱學大考『絕熱壓縮後壓強比較』，微積分選手利用 P_2 = P_1 (V_1/V_2)^gamma，比體制內學生憑空猜測快 10 倍秒殺。'}, {'id': 'K1 20.2', 'desc': '體制內考題秒殺：等溫膨脹熱量計算，微積分學員由 Q = W = nRT ln(V_2/V_1) 1 行直接寫出熱量。'}, {'id': 'K1 20.3', 'desc': '體制內考題秒殺：P-V 圖循環效率問題，微積分選手迅速求出封閉圖形幾何面積與吸熱積分，1 分鐘搞定壓軸大題。'}]}}, {'id': 21, 'title': '三位一體儲能本質：動能、電容能與電感能的「1/2」狀態空間積分（相空間三角形對偶）', 'book_blueprint': '高中物理有三大死背儲能公式：質點動能 E_k = 1/2 m v^2、電容器電場儲能 E_C = 1/2 C V^2 = Q^2/(2C)、電感器磁場儲能 E_L = 1/2 L I^2。高中課本只告訴學生結論，卻從不講這三個『1/2』為什麼在數學上是同構的。本章在相空間（State Space）中展開統一微積分審判：做功微元 dW = F dx，引入動量時間微商 F = dp/dt，利用鏈鎖律 dx/dt = v 導出普遍微分式 dE = v dp；在 (p, v) 坐標系中，牛頓質點 p = mv 為過原點直線，其定積分面積必為直角三角形，因而誕生係數 1/2！同理，電容充能微元 dW = V dq，因 q = CV 為線性關係，積分 int_0^Q (q/C) dq 為 (q, V) 平面直角三角形面積 1/2 Q V；電感微元 dW = E_ind dq = (L di/dt)(i dt) = L i di，積分 int_0^I L i di 為 (i, Phi) 平面三角形面積 1/2 L I^2。最後對比狹義相對論中光子 E = pc，其相空間做功軌跡為垂直或矩形積分，因而沒有 1/2，徹底建立三位一體儲能的微積分幾何大一統。', 'dojo_core': '黑板四分區實彈攻防：一區以三條並列軸線畫出 (p, v)、(q, V)、(Phi, I) 三大狀態空間圖，塗滿三個斜率分別為 1/m, 1/C, L 的底層三角形；二區無跳步推導 dE = v dp、dW = V dq、dW = L i di 三大通用微元；三區以反例對決光子 E = pc 的無 1/2 矩形微元；四區推導變質量系統或非線性介質下的非 1/2 修正，徹底擊碎死記硬背。', 'formulas': [{'id': 'Eq 21.1', 'name': '機械做功微元動量表達式', 'latex': '\\mathrm{d}W = F\\,\\mathrm{d}x = \\left(\\frac{\\mathrm{d}p}{\\mathrm{d}t}\\right)\\mathrm{d}x = v\\,\\mathrm{d}p'}, {'id': 'Eq 21.2', 'name': '動能狀態空間三角形定積分式', 'latex': "E_k = \\int_0^p v(p')\\,\\mathrm{d}p' = \\int_0^p \\frac{p'}{m}\\,\\mathrm{d}p' = \\frac{p^2}{2m} = \\frac{1}{2}mv^2"}, {'id': 'Eq 21.3', 'name': '電容充電微元做功定義式', 'latex': '\\mathrm{d}W_C = V(q)\\,\\mathrm{d}q = \\frac{q}{C}\\,\\mathrm{d}q'}, {'id': 'Eq 21.4', 'name': '電容儲能狀態空間定積分式', 'latex': 'E_C = \\int_0^Q \\frac{q}{C}\\,\\mathrm{d}q = \\frac{Q^2}{2C} = \\frac{1}{2}CV^2'}, {'id': 'Eq 21.5', 'name': '自感反電動勢微元做功定義式', 'latex': '\\mathrm{d}W_L = \\mathcal{E}_L\\,\\mathrm{d}q = \\left(L\\frac{\\mathrm{d}i}{\\mathrm{d}t}\\right)(i\\,\\mathrm{d}t) = L i\\,\\mathrm{d}i'}, {'id': 'Eq 21.6', 'name': '電感儲能狀態空間定積分式', 'latex': "E_L = \\int_0^I L i'\\,\\mathrm{d}i' = \\frac{1}{2}L I^2"}, {'id': 'Eq 21.7', 'name': '光子相空間做功對比式', 'latex': 'E_{\\text{photon}} = \\int_0^p c\\,\\mathrm{d}p = pc \\quad (\\text{速度恆為 } c \\text{，矩形無 } 1/2)'}], 'problems': {'worked_examples': [{'id': 'Ex 21.1', 'desc': '證明 dE = v dp 在狹義相對論 p = gamma m_0 v 下的積分恰好給出 E = m c^2 - m_0 c^2，在低速極限 v << c 展開泰勒級數恢復出 1/2 m_0 v^2。'}, {'id': 'Ex 21.2', 'desc': '以平行板電容器為例，當極板間填入非線性鐵電材料使得 q = C_0 V + alpha V^3 時，無跳步計算充電至電壓 V_0 所需的總功，指出為何儲能不再是 1/2 C V_0^2。'}, {'id': 'Ex 21.3', 'desc': '一超導線圈自感為 L，通以電流 I_0；若迴路電阻突變為 R，列出能量釋放的定積分式 int_0^inf i^2 R dt，證明其總熱量嚴格等於 1/2 L I_0^2。'}], 'margin_inquiries': [{'id': 'Q1 21.1', 'desc': '為何彈簧彈性位能 1/2 k x^2 與動能 1/2 m v^2 的 1/2 來源完全同構？如果力與位移是非線性的 F = k x^3，係數會變成多少？'}, {'id': 'Q1 21.2', 'desc': '電池對電容充電 Q 時，電池做功 W = Q V = C V^2，但電容儲能僅 1/2 C V^2，另外的 1/2 跑去哪裡了？'}, {'id': 'Q1 21.3', 'desc': '在相空間中，光子的積分軌跡為什麼是一條水平直線而不是斜線？這如何導致光子能量沒有 1/2？'}], 'foundational_drills': [{'id': 'P1 21.1', 'desc': '閉卷在紙上推導三位一體儲能公式：在同一個坐標系中分別標出動能、電容能與電感能的微元矩形與三角形幾何面積。'}, {'id': 'P1 21.2', 'desc': '質量為 m 的物體受阻力 F = -k v 做功，利用 dE = v dp 計算速度自 v_0 減速至 0 過程中所損失的全部動能。'}, {'id': 'P1 21.3', 'desc': '一電容器在充電過程中電壓按 V(t) = alpha t 線性增加，計算在 t in [0, T] 區間內的瞬時功率 P(t) 與總儲能。'}, {'id': 'P1 21.4', 'desc': '已知電感反電動勢公式 E = -L di/dt，求通電電流由 0 增加至 I 過程中克服反電動勢所做的總外力功。'}], 'interdisciplinary_applications': [{'id': 'P5 21.1', 'desc': '【LC 振盪電路能量守恆】證明在理想 LC 迴路中，任何瞬間 1/2 C V(t)^2 + 1/2 L I(t)^2 的時間導數恆等於 0。'}, {'id': 'P5 21.2', 'desc': '【電磁軌道砲發射】質量為 m 的電樞在磁場 B 下受安培力 F = I L B 加速，利用相空間積分計算出口動能與電感能量的轉換分配。'}, {'id': 'P5 21.3', 'desc': '【微機電 MEMS 梳齒驅動器】梳齒電容隨位移 x 變化 C(x) = C_0 + k x，求固定電壓下電場對可動極板施加的靜電力 F = 1/2 V^2 (dC/dx)。'}, {'id': 'P5 21.4', 'desc': '【光帆推進與能量對比】分別計算推動質量為 m 的飛船達到速度 v 所需的化學動能 1/2 mv^2，與光子推進時雷射光束所需的總能量 E = pc，比較其效率。'}], 'deepwater_challenges': [{'id': 'P9 21.1', 'desc': '非線性電感飽和：磁通量 Phi(i) = Phi_0 tanh(i / I_s)，嚴格計算電流從 0 上升至 2 I_s 時電感儲存的總磁場能量。'}, {'id': 'P9 21.2', 'desc': '相對論質點做功：證明外力做功 W = int F dx 恆等於 (gamma - 1) m_0 c^2，並在黑板上畫出 p-v 曲線如何在接近光速 c 時劇烈上翹。'}], 'dojo_defense_tasks': [{'id': 'D1 21.1', 'desc': '學員推導電容儲能寫出 W = F dx，導師當場叫停：『電容裡面哪來的位移 x？立刻改用電荷微元 dq 重寫做功微元式！』'}, {'id': 'D1 21.2', 'desc': '學員稱『因為動能是 1/2 mv^2，所以所有儲能都帶 1/2』，導師質問：『光子能量 E = pc 的 1/2 在哪裡？在黑板畫出相空間圖回答！』'}, {'id': 'D1 21.3', 'desc': '學員推導電感儲能忘記考慮反電動勢方向，導師截停：『你的外加電壓與感應電動勢符號為何相反？列出克希荷夫電壓迴路定理澄清！』'}], 'unseen_sandbox_scenarios': [{'id': 'U1 21.1', 'desc': '未知破局：設某超導儲能環的自感 L(i) 隨電流呈現二次衰減 L(i) = L_0 (1 - beta i^2)，要求學員當場導出其儲能公式與飽和極限。'}, {'id': 'U1 21.2', 'desc': '未知破局：一彈簧的恢復力受溫度影響 k(T) = k_0 (1 - alpha T)，在絕熱壓縮過程中求力學做功與溫度微元的聯立微分方程。'}, {'id': 'U1 21.3', 'desc': '未知破局：給定一壓電陶瓷材料，其電荷與位移呈雙線性耦合 q = C V + d x, F = -k x + d V，計算系統總儲能微元 dU 的全微分閉環。'}], 'system_trivialization_arsenal': [{'id': 'K1 21.1', 'desc': "體制內考題秒殺：高中物理『平行板電容充電後斷開電源，拉開兩板間距 d 為 2d，外力做功為何？』微積分選手直接寫下 Delta E = Q^2/(2C') - Q^2/(2C) = 1/2 Q^2 (2d - d)/(epsilon A) 10 秒解出。"}, {'id': 'K1 21.2', 'desc': '體制內考題秒殺：高中大考電路題『自感為 2H 的線圈通過 3A 電流，儲存磁能為何？』微積分選手心算 1/2 * 2 * 3^2 = 9 J 秒殺。'}, {'id': 'K1 21.3', 'desc': '體制內考題秒殺：變力作功動能定理題，體制內拆解割補，微積分選手列出 int v dp 直接求三角形面積一筆勾銷。'}]}}, {'id': 22, 'title': '電流磁效應微元場積分：畢奧-薩伐爾定律與長直導線、圓線圈、螺線管磁場', 'book_blueprint': '高中選修物理電磁學的三大死背公式：載流長直導線磁場 B = mu_0 I / (2 pi r)、載流圓線圈中心磁場 B = mu_0 I / (2 R)、理想長螺線管內部磁場 B = mu_0 n I。教科書僅以『安培發現』一筆帶過，導致學生根本無法理解為何長直導線分母帶有 2pi，而圓線圈卻只有 2。本章徹底以畢奧-薩伐爾定律（Biot-Savart Law）微元向量積分為核心：電流微元 dB = (mu_0 I / 4pi) * (dl x r_hat) / r^2；針對無窮長長直導線，沿導線取微元 dl = dx，幾何代換 x = r tan(theta)，積分區間自 -pi/2 掃描至 +pi/2，定積分 int_{-pi/2}^{pi/2} cos(theta) dtheta = 2，分母 4pi 消除為 2pi r，嚴格誕生 B = mu_0 I / (2 pi r)；針對圓線圈軸線上一點，微元 dl 與位置向量始終垂直，利用軸向對稱性消去徑向分量，積分得 B(x) = mu_0 I R^2 / [2(R^2+x^2)^{3/2}]，令 x=0 瞬間還原中心磁場 mu_0 I / (2R)；最後建立安培環路定理 oint B dl = mu_0 I_enc，以矩形路徑嚴格推導長螺線管磁場 B = mu_0 n I，完成高中電磁學微積分大破局。', 'dojo_core': '黑板四分區實彈攻防：一區在黑板畫出長直導線、圓線圈軸線、螺線管截面的微元空間向量圖，明確標註 dl、r 向量與叉積方向；二區在黑板無跳步推導長直導線角度代換積分（tan theta 代換），讓學生親眼見證 2pi 的幾何來源；三區推導圓線圈軸向對稱抵消，導出任意位置公式並退化為中心解；四區以安培環路矩形動線秒殺螺線管內部勻強磁場，對決外場為零的物理圖像。', 'formulas': [{'id': 'Eq 22.1', 'name': '畢奧-薩伐爾定律微元式', 'latex': '\\mathrm{d}\\vec{B} = \\frac{\\mu_0 I}{4\\pi} \\frac{\\mathrm{d}\\vec{\\ell} \\times \\hat{r}}{r^2}'}, {'id': 'Eq 22.2', 'name': '長直導線微元角度代換式', 'latex': 'x = r_0 \\tan\\theta, \\quad \\mathrm{d}x = r_0 \\sec^2\\theta\\,\\mathrm{d}\\theta, \\quad r = r_0 \\sec\\theta'}, {'id': 'Eq 22.3', 'name': '載流無窮長直導線磁場積分式', 'latex': 'B = \\int_{-\\infty}^{\\infty} \\frac{\\mu_0 I}{4\\pi} \\frac{\\sin\\phi\\,\\mathrm{d}x}{r^2} = \\frac{\\mu_0 I}{4\\pi r_0} \\int_{-\\pi/2}^{\\pi/2} \\cos\\theta\\,\\mathrm{d}\\theta = \\frac{\\mu_0 I}{2\\pi r_0}'}, {'id': 'Eq 22.4', 'name': '載流圓線圈軸線磁場定積分式', 'latex': 'B(x) = \\oint \\mathrm{d}B_x = \\frac{\\mu_0 I}{4\\pi (R^2+x^2)} \\cos\\alpha \\oint \\mathrm{d}\\ell = \\frac{\\mu_0 I R^2}{2(R^2+x^2)^{3/2}}'}, {'id': 'Eq 22.5', 'name': '載流圓線圈中心磁場退化式', 'latex': 'B(0) = \\frac{\\mu_0 I}{2R}'}, {'id': 'Eq 22.6', 'name': '安培環路定理積分形式', 'latex': '\\oint \\vec{B} \\cdot \\mathrm{d}\\vec{\\ell} = \\mu_0 I_{\\text{enc}}'}, {'id': 'Eq 22.7', 'name': '理想長螺線管內部勻強磁場式', 'latex': '\\oint_{\\text{rect}} \\vec{B}\\cdot\\mathrm{d}\\vec{\\ell} = B L + 0 + 0 + 0 = \\mu_0 (n L I) \\implies B = \\mu_0 n I'}], 'problems': {'worked_examples': [{'id': 'Ex 22.1', 'desc': '有限長直導線載有電流 I，兩端點對觀察點張角分別為 theta_1 與 theta_2；利用畢奧-薩伐爾定律導出其磁場 B = (mu_0 I / 4pi r) * (sin theta_2 - sin theta_1)，並取極限定出無窮長情形。'}, {'id': 'Ex 22.2', 'desc': '亥姆霍茲線圈（Helmholtz Coils）：由兩個相距為 R、共軸同向的同型圓線圈組成；利用 B(x) 公式求中心中點處的磁場與一階、二階導數，證明該中點附近磁場具備高度勻強性（d^2B/dx^2 = 0）。'}, {'id': 'Ex 22.3', 'desc': '厚壁圓柱導體內外半徑為 a 與 b，均勻通以電流 I；利用安培環路定理分別求 r < a、a <= r <= b、r > b 三個區域的磁場分佈函數並作圖。'}], 'margin_inquiries': [{'id': 'Q1 22.1', 'desc': '為什麼長直導線磁場公式分母有 pi（2 pi r），而圓線圈中心磁場公式分母沒有 pi（2 R）？從被積函數的幾何對稱性解釋。'}, {'id': 'Q1 22.2', 'desc': '在推導螺線管磁場時，我們假設管外磁場為 0，這在物理上依賴什麼近似？如果螺線管長度有限，端點磁場會衰減為多少？'}, {'id': 'Q1 22.3', 'desc': '安培環路定理能用來計算任意形狀電流的磁場嗎？為什麼求圓線圈中心磁場必須用畢奧-薩伐爾積分而不能直接用安培環路？'}], 'foundational_drills': [{'id': 'P1 22.1', 'desc': '手算長度為 L 的正方形載流線圈（電流 I）中心點的磁場，利用 4 根有限長直導線公式疊加。'}, {'id': 'P1 22.2', 'desc': '半徑為 R 的半圓形載流導線，在其圓心處產生的磁場，利用微元法 1 行寫出其大小。'}, {'id': 'P1 22.3', 'desc': '長螺線管每公分繞有 50 匝線圈，通以 2A 電流，求管內中心磁場強度（mu_0 = 4pi * 10^-7 T*m/A）。'}, {'id': 'P1 22.4', 'desc': '載流圓環軸線上一點與中心距離等於線圈半徑 x = R，求該處磁場與中心磁場的比值 B(R) / B(0)。'}], 'interdisciplinary_applications': [{'id': 'P5 22.1', 'desc': '【核磁共振 MRI 主磁體】利用超導螺線管產生 3 特斯拉勻強磁場，線圈匝數密度為 1000 匝/米，求所需的超導電流大小並計算其內部磁能密度 u_B = B^2 / (2 mu_0)。'}, {'id': 'P5 22.2', 'desc': '【地球磁場發電機模型】將地核外層對流電流近似為赤道面上的環形大電流，由地表兩極磁場反推地核等效等效磁偶極矩 m = I * A。'}, {'id': 'P5 22.3', 'desc': '【質譜儀偏轉軌跡】帶電粒子穿過載流螺線管軸向磁場，利用勞侖茲力與向心加速度微商方程計算粒子迴旋半徑 r = mv / (qB)。'}, {'id': 'P5 22.4', 'desc': '【平行雙導線相互安培力】兩根相距為 d 的平行長直導線分別載有電流 I_1, I_2，推導單位長度受力 f = mu_0 I_1 I_2 / (2 pi d)，闡述國際單位制安培（A）的歷史微積分定義。'}], 'deepwater_challenges': [{'id': 'P9 22.1', 'desc': '均勻帶電球面（半徑 R，總電荷 Q）以角速度 omega 繞對稱軸自轉；將其切分為無窮多個緯度環狀電流微元，定積分求出球心處的總磁場 B = (mu_0 Q omega) / (6 pi R)。'}, {'id': 'P9 22.2', 'desc': '長直載流圓柱體內部存在偏心圓柱形空洞；利用磁場疊加原理與向量分析，證明空洞內部磁場恆為嚴格勻強磁場並求其向量表達式。'}], 'dojo_defense_tasks': [{'id': 'D1 22.1', 'desc': '學員計算圓線圈中心磁場試圖取安培環路，導師截停：『圍繞線圈取圓形路徑，磁場在環路上大小均勻嗎？方向相切嗎？立刻退回畢奧-薩伐爾定律手算！』'}, {'id': 'D1 22.2', 'desc': '學員在長直導線積分中直接寫出 int 1/r^2 dx，導師指出：『微元到場點的距離 r 是變量！在黑板寫出幾何三角代換關係式！』'}, {'id': 'D1 22.3', 'desc': '學員聲稱『只要封閉曲線內電流為 0，曲線上一點的磁場必為 0』，導師在黑板畫出雙平行導線外部環路，當場反證該思維漏洞。'}], 'unseen_sandbox_scenarios': [{'id': 'U1 22.1', 'desc': '未知破局：兩條夾角為 90 度的半無窮長折線導線載有電流 I，求折角角平分線上距頂點 d 處的磁場。'}, {'id': 'U1 22.2', 'desc': '未知破局：阿基米德螺線電流 r = a theta (0 <= theta <= 2pi)，求其在原點處產生的磁場定積分表達式。'}, {'id': 'U1 22.3', 'desc': '未知破局：平板薄銅帶寬度為 w，均勻流過總電流 I，求銅帶正上方高度 h 處的磁場大小。'}], 'system_trivialization_arsenal': [{'id': 'K1 22.1', 'desc': '體制內考題秒殺：高中大考『兩平行動態導線間中點磁場』，微積分學員由 B = mu_0 I / (2pi r) 向量直接相消或翻倍，3 秒寫出答案。'}, {'id': 'K1 22.2', 'desc': '體制內考題秒殺：圓線圈軸線磁場比較題，微積分學員調用 B(x) 正比於 (R^2+x^2)^{-3/2} 迅速得出衰減比。'}, {'id': 'K1 22.3', 'desc': '體制內考題秒殺：螺線管中間剖開磁場，微積分選手利用對稱性知端點磁場剛好是內部的一半 1/2 mu_0 n I，瞬間秒殺。'}]}}, {'id': 23, 'title': '剛體連續質量分佈與轉動慣量微元積分（細棒、圓盤、球體與平行軸定理）', 'book_blueprint': '高中物理講到剛體轉動，教科書直接給出一連串冷冰冰的公式：均勻細棒繞端點 1/3 M L^2、繞中心 1/12 M L^2、均勻圓盤 1/2 M R^2、球殼 2/3 M R^2、實心球 2/5 M R^2。學生只能像背圓周率一樣死背，一旦遇到非均勻密度或旋轉軸偏移直接束手無策。本章徹底拆解轉動慣量微積分定義式 I = int r^2 dm：均勻細棒建立線密度微元 dm = (M/L) dx，定積分 int_{-L/2}^{L/2} x^2 dx = 1/12 M L^2，端點積分 int_0^L x^2 dx = 1/3 M L^2；圓盤採用同心圓環微元法 dm = (M / (pi R^2)) * (2 pi r dr)，積分 int_0^R r^2 (2 r dr) 誕生 1/2 M R^2；實心球採用薄圓盤堆疊或薄球殼積分，無跳步導出 2/5 M R^2；最後以定積分展開式 I = int (x_cm + d)^2 dm 嚴格證明平行軸定理 I = I_cm + M d^2，徹底解放剛體力學降維打擊力。', 'dojo_core': '黑板四分區實彈攻防：一區在黑板畫出細棒、圓盤、實心球的三重微元幾何剖分圖（線微元 dx、環微元 2pi r dr、盤微元 pi(R^2-z^2) dz）；二區無跳步推導出 1/12、1/2、2/5 的定積分係數來源；三區用代數展開法證明平行軸定理，用交叉項 int x_cm dm = 0 揭示質心坐標定義的威力；四區以非均勻密度棒 lambda(x) = k x 突襲學員，展示微積分第一性原理的通用性。', 'formulas': [{'id': 'Eq 23.1', 'name': '轉動慣量微元定義式', 'latex': 'I = \\int r^2\\,\\mathrm{d}m'}, {'id': 'Eq 23.2', 'name': '均勻細棒繞質心轉動慣量積分式', 'latex': 'I_{\\text{rod, cm}} = \\int_{-L/2}^{L/2} x^2 \\left(\\frac{M}{L}\\mathrm{d}x\\right) = \\frac{1}{12} M L^2'}, {'id': 'Eq 23.3', 'name': '均勻細棒繞端點轉動慣量積分式', 'latex': 'I_{\\text{rod, end}} = \\int_0^L x^2 \\left(\\frac{M}{L}\\mathrm{d}x\\right) = \\frac{1}{3} M L^2'}, {'id': 'Eq 23.4', 'name': '均勻圓盤薄環微元定積分式', 'latex': 'I_{\\text{disk}} = \\int_0^R r^2 \\left(\\frac{2M}{R^2} r\\,\\mathrm{d}r\\right) = \\frac{1}{2} M R^2'}, {'id': 'Eq 23.5', 'name': '薄球殼轉動慣量積分式', 'latex': 'I_{\\text{shell}} = \\frac{2}{3} M R^2'}, {'id': 'Eq 23.6', 'name': '均勻實心球薄盤疊加定積分式', 'latex': 'I_{\\text{sphere}} = \\int_{-R}^R \\frac{1}{2}\\left[\\rho \\pi (R^2 - z^2)\\mathrm{d}z\\right](R^2 - z^2) = \\frac{2}{5} M R^2'}, {'id': 'Eq 23.7', 'name': '剛體平行軸定理微積分展開式', 'latex': "I = \\int (x' + d)^2\\,\\mathrm{d}m = I_{\\text{cm}} + 2d\\int x'\\,\\mathrm{d}m + M d^2 = I_{\\text{cm}} + M d^2"}], 'problems': {'worked_examples': [{'id': 'Ex 23.1', 'desc': '非均勻長細棒長度為 L，線密度隨位置線性增加 lambda(x) = k x (0 <= x <= L)；求棒的總質量 M、質心位置 x_cm，以及繞端點 x=0 的轉動慣量 I_0。'}, {'id': 'Ex 23.2', 'desc': '以均勻薄圓盤 I = 1/2 M R^2 為微元，利用圓盤疊加法詳細推導均勻實心圓錐繞對稱軸旋轉的轉動慣量 I = 3/10 M R^2。'}, {'id': 'Ex 23.3', 'desc': '直徑為 2R 的均勻薄圓盤，邊緣挖去一個直徑為 R 的小圓孔；利用負質量法與平行軸定理，計算該殘缺圓盤繞中心軸的轉動慣量。'}], 'margin_inquiries': [{'id': 'Q1 23.1', 'desc': "在平行軸定理的推導中，展開項 2d int x' dm 為什麼恰好等於 0？這與質心的物理定義有何本質聯繫？"}, {'id': 'Q1 23.2', 'desc': '為什麼薄球殼的係數是 2/3，而實心球是 2/5？為何實心球的係數比薄球殼更小？從質量分佈幾何半徑的角度解釋。'}, {'id': 'Q1 23.3', 'desc': '平面薄板垂直軸定理 I_z = I_x + I_y 的微積分證明依據是什麼？它適用於三維球體嗎？'}], 'foundational_drills': [{'id': 'P1 23.1', 'desc': '利用平行軸定理，由細棒繞中心轉動慣量 1/12 M L^2 直接推導出繞端點旋轉的轉動慣量 1/3 M L^2。'}, {'id': 'P1 23.2', 'desc': '求內徑為 R_1、外徑為 R_2 的均勻厚圓環繞中心垂直軸的轉動慣量 I = 1/2 M (R_1^2 + R_2^2)。'}, {'id': 'P1 23.3', 'desc': '設細棒線密度為二次分佈 lambda(x) = alpha x^2 (-L/2 <= x <= L/2)，求其繞質心旋轉的轉動慣量。'}, {'id': 'P1 23.4', 'desc': '邊長為 a 的均勻正方形薄板，求其繞垂直於板面且過中心的軸之轉動慣量。'}], 'interdisciplinary_applications': [{'id': 'P5 23.1', 'desc': '【斜面滾動下落競速】半徑皆為 R、質量皆為 M 的圓環、圓盤與實心球自同高度斜面無滑動滾下，利用機械能守恆 E = 1/2 M v^2 + 1/2 I omega^2 證明到達底部速度大小順序為球 > 盤 > 環。'}, {'id': 'P5 23.2', 'desc': '【物理擺單擺週期修正】質量均勻的細棒懸掛於一端做微小振盪，利用物理擺週期公式 T = 2pi sqrt{I / (M g d_cm)} 計算其週期，並與質點單擺進行對比。'}, {'id': 'P5 23.3', 'desc': '【飛輪儲能系統設計】高速旋轉飛輪儲存動能 E = 1/2 I omega^2，在材料極限抗拉應力限制下，比較薄環與圓盤的最佳儲能密度。'}, {'id': 'P5 23.4', 'desc': '【行星自轉角動量】將地球視為均勻球體（M=5.97e24 kg, R=6371 km），計算其自轉角動量 L = I omega，並估算自轉減慢釋放的微元能量。'}], 'deepwater_challenges': [{'id': 'P9 23.1', 'desc': '均勻實心橢球 (x/a)^2 + (y/b)^2 + (z/c)^2 <= 1，利用三維橢球座標換元微積分，無跳步證明其繞 z 軸的轉動慣量為 1/5 M (a^2 + b^2)。'}, {'id': 'P9 23.2', 'desc': '非均勻地球密度模型：rho(r) = rho_0 (1 - alpha r/R)，求地球真實轉動慣量係數 k = I / (M R^2)，解釋為何實測值 0.3308 小於均勻球體的 0.4。'}], 'dojo_defense_tasks': [{'id': 'D1 23.1', 'desc': '學員推導圓盤轉動慣量寫出 dm = (M/R) dr，導師截停：『二維圓盤的質量怎能按長度分佈？立刻寫出面密度 sigma 與面積微元 dA = 2pi r dr！』'}, {'id': 'D1 23.2', 'desc': '學員試圖對任意物體使用垂直軸定理 I_z = I_x + I_y，導師質問：『球體的 z 軸能等於 x 軸加 y 軸嗎？在黑板寫出該定理成立的幾何條件！』'}, {'id': 'D1 23.3', 'desc': '學員計算平行軸定理忘記 d 是到『質心軸』的距離，導師以端點轉動慣量為基準突襲，要求學員指證其違規之處。'}], 'unseen_sandbox_scenarios': [{'id': 'U1 23.1', 'desc': '未知破局：給定一均勻等邊三角形薄板，求其繞過質心且垂直於板面的轉動慣量（禁止直接套用現成公式）。'}, {'id': 'U1 23.2', 'desc': '未知破局：螺旋線剛體模型，金屬絲繞成螺距為 h、半徑為 R 的圓柱螺旋線，求其繞圓柱對稱軸的轉動慣量。'}, {'id': 'U1 23.3', 'desc': '未知破局：空心薄壁圓柱體內部充滿黏性液體，在轉動加速瞬間液體未跟隨旋轉，求有效轉動慣量隨時間的動態演化微分方程。'}], 'system_trivialization_arsenal': [{'id': 'K1 23.1', 'desc': '體制內考題秒殺：高中大考剛體下滾題，體制內學生糾結摩擦力方向，微積分學員寫下 a = g sin(theta) / (1 + I/(MR^2)) 5 秒得出加速度。'}, {'id': 'K1 23.2', 'desc': '體制內考題秒殺：偏心轉動慣量求法，微積分學員使用平行軸定理 I = I_cm + Md^2 1 行代入秒殺。'}, {'id': 'K1 23.3', 'desc': '體制內考題秒殺：細棒繞 1/3 處旋轉週期，微積分選手迅速求出 I = 1/12 ML^2 + M(L/6)^2 = 1/9 ML^2，10 秒鎖定週期。'}]}}]}
